-- Comp DIODE-609 (Arturia): compress/limit rows for both channels, gain reduction meters, mix, power, sidechain EQ strip and input drive; bright knob labels.
local SFX = require('src.Functions.Stock FX UI') local P = {} local function add(k, n, base) for i = 1, 2 do P[k..i] = { 'Ch.'..i..': '..n, idx = base + i - 1 } end end add('cin', 'Enable Comp', 4) add('cth', 'Comp threshold', 6) add('cat', 'Comp attack', 8) add('crc', 'Comp recovery', 10) add('crt', 'Comp ratio', 12) add('cmu', 'Comp make-up gain', 14) add('lin', 'Enable Limiter', 16) add('lfa', 'Enable Limiter Fast Attack', 18) add('lth', 'Limiter threshold', 20) add('lrc', 'Limiter recovery', 22) P.mix = { 'Dry/Wet Mix', idx = 26 } P.ext = { 'Enable External Side Chain', idx = 27 } P.la = { 'Look-ahead On/Off', idx = 28 } P.lat = { 'Look-ahead time', idx = 29 } P.sce = { 'SC EQ On/Off', idx = 30 } P.hpf = { 'SC EQ HPF Frequency', idx = 31 } P.mf = { 'SC EQ Mid Frequency', idx = 32 } P.mg = { 'SC EQ Mid Gain', idx = 33 } P.hs = { 'SC EQ Hi-Shelf Gain', idx = 34 } P.drive = { 'Input Drive', idx = 35 } P.listen = { 'Sidechain Listen', idx = 36 } P.gr = { 'Out Max Gain Reduction', idx = 37 } P.pwr = { 'Power On/Off', idx = 1 } P.ms = { 'LR / MS Mode', idx = 2 } P.st = { 'Stereo Mode', idx = 3 } local D = SFX.Begin({ Title = 'Comp DIODE-609', W = 800, Accent = SFX.ACCENT.Dynamics, Params = P }) if not D then return end local A = SFX.A local BG, EDGE, TXT, ACC, LED = 0x3F4C86FF, 0x93A3DAFF, 0xEEF1FFFF, 0x2F67DCFF, 0xFF5A3CFF local LBL = 0xFFFFFFFF D:Rect(0, 0, 808, 216, BG, 0, true) local function Kn(key, cx, cy, label, o) o = o or {} o.accent = o.accent or ACC D:Knob(key, cx, cy, 'M', '', o) D:Text(cx, cy - 27, LBL, label, 8, 'c', true) end local function Sw(id, key, x, y, w, label) local on = D:Get(key) < 0.5 local clicked = D:Btn(id, x, y, w, 17) if clicked then D:Set(key, on and 1 or 0) end D:Rect(x, y, w, 17, on and A(ACC, 0.35) or 0x2A3466FF, 8, true) D:Rect(x, y, w, 17, EDGE, 8, false, 1) im.DrawList_AddCircleFilled(D.DL, D.X + x + 9, D.Y + y + 8.5, 3, on and LED or 0x555B7AFF) D:Text(x + w / 2 + 4, y + 4, TXT, label, 8, 'c') D:Text(x + w / 2, y - 11, LBL, 'attack', 8, 'c', true) end for i = 1, 2 do local y = (i == 1) and 3 or 73 local cy = y + 33 local sx = (i == 1) and 'L' or 'R' D:Rect(4, y, 340, 68, EDGE, 3, false, 1) D:Text(35, cy - 12, TXT, 'COMPRESS', 9, 'c', true) D:Text(35, cy + 2, TXT, sx, 11, 'c', true) local K = { { 'cth', 'threshold', 'dB' }, { 'cat', 'attack ms', 'ms' }, { 'crc', 'recovery ms' }, { 'cmu', 'makeup gain', 'dB' }, { 'crt', 'ratio' } } for j, k in ipairs(K) do Kn(k[1]..i, 66 + 48 * (j - 0.5), cy, k[2], { unit = k[3] }) end D:Toggle('cin'..i, 308, cy - 8, 32, 'in', { accent = LED }) D:Rect(348, y, 224, 68, EDGE, 3, false, 1) D:Text(372, cy - 12, TXT, 'LIMIT', 9, 'c', true) D:Text(372, cy + 2, TXT, sx, 11, 'c', true) Kn('lth'..i, 419, cy, 'threshold', { unit = 'dB' }) Kn('lrc'..i, 465, cy, 'recovery ms') Sw('fast'..i, 'lfa'..i, 490, cy - 8, 40, 'fast') D:Toggle('lin'..i, 534, cy - 8, 34, 'in', { accent = LED }) end D:Rect(576, 3, 146, 138, EDGE, 3, false, 1) local function meter(x, lbl) D:Text(x + 34, 5, LBL, lbl, 8, 'c', true) local L, T, R, B = D:Panel(x, 16, 68, 52) local cx = (L + R) / 2 local py = B - 5 for i = 0, 5 do local a = -0.8 + 1.6 * i / 5 local s, c = math.sin(a), math.cos(a) im.DrawList_AddLine(D.DL, cx + s * 30, py - c * 30, cx + s * 36, py - c * 36, 0xE8ECF8FF, 1) end local v = SFX.Clamp(D:Get('gr'), 0, 1) local a = -0.8 + 1.6 * v im.DrawList_AddLine(D.DL, cx, py, cx + math.sin(a) * 34, py - math.cos(a) * 34, 0xF2F2F2FF, 1.4) end meter(580, 'gain reduction L') meter(652, 'gain reduction R') D:Toggle('st', 582, 84, 54, 'stereo', { accent = LED }) D:Toggle('ms', 582, 106, 54, 'M/S', { accent = LED }) Kn('mix', 690, 108, 'mix', { unit = '%' }) D:Rect(726, 3, 70, 138, EDGE, 3, false, 1) D:Toggle('pwr', 731, 30, 60, 'on', { accent = LED }) D:Text(761, 82, TXT, 'Comp', 12, 'c') D:Text(761, 98, TXT, 'DIODE-609', 9, 'c') D:Rect(4, 143, 792, 68, EDGE, 3, false, 1) D:Text(37, 158, LBL, 'side chain', 8, 'c', true) D:Toggle('ext', 8, 173, 58, 'external', { accent = LED }) Kn('lat', 100, 176, 'look ahead', { unit = 'ms' }) D:Toggle('la', 126, 168, 34, 'in', { accent = LED }) D:Line(168, 150, 168, 205, EDGE, 1) Kn('hpf', 204, 176, 'high pass', { unit = 'Hz' }) Kn('mf', 252, 176, 'mid freq', { unit = 'Hz' }) Kn('mg', 300, 176, 'mid gain', { unit = 'dB', bipolar = true }) Kn('hs', 348, 176, 'high shelf', { unit = 'dB', bipolar = true }) D:Toggle('sce', 372, 168, 34, 'in', { accent = LED }) D:Line(414, 150, 414, 205, EDGE, 1) D:Text(462, 158, LBL, 'side chain', 8, 'c', true) D:Toggle('listen', 430, 173, 64, 'listen', { accent = LED }) Kn('drive', 560, 176, 'input drive', { unit = 'dB' }) im.SetCursorScreenPos(ctx, D.X + 640, D.Y + 165) Presets.Button(140, 22) D:End()